def ck(k,x):
 checks[k]=bool(x)
 if not x:raise AssertionError(k)
def ct(k,x):
 controls[k]=bool(x)
 if not x:raise AssertionError('contrary '+k)
def ball(x):
 x=F(x);return arb(x.numerator)/x.denominator
def w(a,b):
 a,b=F(a),F(b)
 if b<=a:return arb(0)
 return (1+ball((b-a)**2/(2*(a+b)*(2-a-b)))).log()
def bernstein_nonnegative(power,maxdepth=40):
 if len(power)!=4:raise ValueError('cubic required')
 p0,p1,p2,p3=map(F,power);bs=[p0,p0+p1/3,p0+2*p1/3+p2/3,p0+p1+p2+p3];stack=[(bs,0)];nodes=0
 while stack:
  b,d=stack.pop();nodes+=1
  if min(b)>=0:continue
  if max(b)<0 or d>=maxdepth:return False,nodes
  row=b;left=[row[0]];right=[row[-1]]
  for _ in range(3):
   row=[(row[i]+row[i+1])/2 for i in range(len(row)-1)];left.append(row[0]);right.append(row[-1])
  stack.extend([(left,d+1),(right[::-1],d+1)])
 return True,nodes
def cubic(u,b,lam,mu):
 D0,D1,D2=8-3*b,8-10*b,-3*b
 return [-mu*D0+4*lam,u*D0-mu*D1-8*lam,u*D1-mu*D2+4*lam,u*D2]
def lower_min(u,b,lam):
 from scipy.optimize import minimize_scalar
 # Inexact selection cannot bypass the exact polynomial certificate.
 uf,bf,lf=map(float,(u,b,lam))
 def f(r):return r*uf+lf*4*(1-r)**2/(8*(1+r)-bf*(3+10*r+3*r*r))
 z=minimize_scalar(f,bounds=(0,1),method='bounded',options={'xatol':1e-13})
 proposed=min(f(0),f(1),z.fun)
 mu=F(floor((proposed-1e-7)*10**6),10**6)
 for _ in range(100):
  ok,nodes=bernstein_nonnegative(cubic(u,b,lam,mu))
  if ok:return mu,nodes
  mu-=F(1,10**6)
 raise ArithmeticError('candidate bound not certified')
def certificate(knots,values,lam,supplied=None):
 knots=list(map(F,knots));values=list(map(F,values));lam=F(lam)
 if len(knots)!=len(values) or len(knots)<2 or knots[0]!=0 or not 0<knots[-1]<=F(1,2) or any(b<=a for a,b in zip(knots,knots[1:])) or values[0]!=1 or min(values)<0 or lam<0:raise ValueError('certificate domain')
 if supplied is not None and len(supplied)!=(len(knots)-1)*len(knots)//2:raise ValueError("cell-bound coverage")
 delta=F(0);worst=None;cells=nodes=0;accepted=[]
 for i in range(len(knots)-1):
  xl,xh=knots[i:i+2];sl=(values[i+1]-values[i])/(xh-xl)
  for j in range(i,len(knots)-1):
   yl,yh=knots[j:j+2];sr=(values[j+1]-values[j])/(yh-yl)
   def ux(x):return values[i]+sl*(x-xl)
   def uy(y):return values[j]+sr*(y-yl)
   verts=[(x,y) for x in (xl,xh) for y in (yl,yh) if y>x]
   H=max((ux(x)-uy(y))/(y-x) for x,y in verts)
   if xh>=yl:H=max(H,-sl,-sr)
   u=min(values[j:j+2]);b=max(F(0),yl-xh)
   if supplied is None:mu,nn=lower_min(u,b,lam)
   else:
    mu=F(supplied[cells]);ok,nn=bernstein_nonnegative(cubic(u,b,lam,mu))
    if not ok:raise ArithmeticError("saved cell bound is unproved")
   nodes+=nn;cells+=1;accepted.append(str(mu))
   if H-mu>delta:delta=H-mu;worst=[i,j,str(H),str(mu)]
 return delta,cells,nodes,worst,accepted
